def flow_svg(key,title):
    nodes=[('🧠','Vault + index'),('⌁','Bracelet 1–3'),('#','Scripts + cache'),('▣','Modèle local'),('✓','Audit + humain')]
    out=[f'<svg class="master-flow" viewBox="0 0 1100 250" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Architecture {html.escape(title)} : cinq cartes reliées">',
         '<defs><marker id="master-arrow-'+key+'" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10z" fill="#297766"/></marker></defs>',
         '<rect width="1100" height="250" rx="12" fill="#fff"/><text x="22" y="28" class="master-kicker">OBSIDIAN CANVAS · '+html.escape(title.upper())+'</text>']
    for i in range(4):
        x=35+i*214;x2=x+194
        out.append(f'<path d="M {x2} 130 C {x2+18} 92 {x2+35} 164 {x2+48} 130" class="master-edge" marker-end="url(#master-arrow-{key})"/>')
    for i,(icon,label) in enumerate(nodes):
        x=22+i*214
        out.append(f'<g class="master-note" transform="translate({x},64)"><rect width="180" height="134" rx="9"/><path d="M9 0H171Q180 0 180 9V38H0V9Q0 0 9 0Z"/><text x="15" y="25" class="master-icon">{icon}</text><text x="47" y="25" class="master-file">note-{i+1}.md</text><text x="14" y="68" class="master-label">{label}</text><text x="14" y="101" class="master-role">'+(['mémoire courte','peu d’outils','0 token','essai borné','preuve verte'][i])+'</text></g>')
    out.append('<text x="22" y="229" class="master-caption">Estimations : coût à mesurer · performance à tester · revue humaine conservée</text></svg>')
    return ''.join(out)

